#include <string.h>
#include <stdint.h>

// Declare the fuzzer function
int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "usage: %s <input-file>\n", argv[0]);
        return 1;
    }
    FILE *fp = fopen(argv[1], "rb");
    if (!fp) {
        perror("fopen");
        return 1;
    }
    fseek(fp, 0, SEEK_END);
    long sz = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    uint8_t *buf = malloc(sz);
    if (sz > 0) {
        fread(buf, 1, sz, fp);
    }
    fclose(fp);

    int ret = LLVMFuzzerTestOneInput(buf, sz);
    free(buf);
    return ret;
}
